/**
 * DocBits release names — user-facing proper nouns for the technical
 * release channels. Identical in every language, deliberately NOT Tolgee
 * keys. The technical channel values ('vesta'/'nova' in the auth API, the
 * 'release_channel' LocalStorage key and host-based routing) are unchanged —
 * this mapping is display-only, and is now the identity mapping (DEVO-135):
 * `vesta` (the current/live chain, unchanged branch names) displays as
 * "Vesta"; `nova` (the early-access chain, `/nova/` bundle) displays as
 * "Nova".
 *
 * Rotating names when a new release ships = edit this file only.
 *
 * Before DEVO-135 the enum values were `latest`/`frozen` and this map
 * INVERTED them for display (`latest` → "Nova", `frozen` → "Vesta") — the
 * same two names meant the opposite thing here vs. in the deploy-gate
 * metrics (`src/services/tests/deployBlockingTestsPrometheus.service.ts`'s `track`
 * label, which has always stamped track="vesta" on branch `dev` and
 * track="nova" on `dev-nova`). DEVO-135 renamed the enum values themselves to
 * `vesta`/`nova`, which resolves that collision — this file and the deploy
 * metrics now agree. See TRACK_LABEL in that service for the (now historical)
 * reasoning on why the two were never aligned before.
 */
export const RELEASE_NAMES: Record<string, string> = {
  vesta: 'Vesta',
  nova: 'Nova',
};

/**
 * Display name for a release channel. Unknown channel values fall back to
 * the raw channel string so the UI never renders an empty badge; a missing
 * channel returns '' (callers hide the badge in that case).
 */
export function getReleaseName(channel?: string | null): string {
  if (!channel) return '';
  return RELEASE_NAMES[channel] ?? channel;
}
